#!/usr/bin/env bash
set -euo pipefail
python3 - "$@" <<'PY'
import sys
import os
import json
import time
import yaml
from datetime import datetime, timezone

APP_DIR = '/app'
MANIFEST_PATH = '/app/pipeline.yaml'
STATE_DIR = '/app/.pipeline'
TEST_RESULTS_PATH = os.path.join(STATE_DIR, 'test_results.json')
DEPLOYMENTS_DIR = os.path.join(STATE_DIR, 'deployments')

SERVICE_FIELDS = ['path', 'build_cmd', 'test_cmd', 'port', 'depends_on', 'health_endpoint']
ENV_FIELDS = ['deploy_target', 'health_check_port', 'max_replicas']

def ensure_state():
    os.makedirs(STATE_DIR, exist_ok=True)
    os.makedirs(DEPLOYMENTS_DIR, exist_ok=True)

def fail(msg, code=1):
    print(f"ERROR: {msg}")
    sys.exit(code)

def now_iso():
    return datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')

def load_json(path, default):
    try:
        with open(path) as f:
            return json.load(f)
    except FileNotFoundError:
        return default
    except json.JSONDecodeError as e:
        fail(f"state error in {path}: {e}")

def save_json(path, data):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w') as f:
        json.dump(data, f, indent=2, sort_keys=True)

def load_manifest():
    try:
        with open(MANIFEST_PATH) as f:
            data = yaml.safe_load(f)
    except FileNotFoundError:
        fail("manifest not found")
    except yaml.YAMLError as e:
        fail(f"YAML syntax error: {e}")
    if not isinstance(data, dict):
        fail("manifest must be a mapping")
    return data

def validate_manifest(data):
    if not isinstance(data, dict):
        raise ValueError("manifest must be a mapping")

    services = data.get('services')
    if not isinstance(services, dict) or not services:
        raise ValueError("manifest missing services")

    environments = data.get('environments')
    if not isinstance(environments, dict) or not environments:
        raise ValueError("manifest missing environments")

    for env_name, env in environments.items():
        if not isinstance(env, dict):
            raise ValueError(f"environment {env_name} must be a mapping")
        for field in ENV_FIELDS:
            if field not in env:
                raise ValueError(f"environment {env_name} missing required field: {field}")

    for name, svc in services.items():
        if not isinstance(svc, dict):
            raise ValueError(f"service {name} must be a mapping")
        for field in SERVICE_FIELDS:
            if field not in svc:
                raise ValueError(f"service {name} missing required field: {field}")
        if not isinstance(svc['depends_on'], list):
            raise ValueError(f"service {name} has invalid depends_on: must be a list")
        for dep in svc['depends_on']:
            if dep not in services:
                raise ValueError(f"service {name} depends on undefined service: {dep}")

    port_map = {}
    for name, svc in services.items():
        port = svc['port']
        if port in port_map:
            raise ValueError(f"duplicate port assignment: {port}")
        port_map[port] = name

    cycle = find_cycle(services)
    if cycle:
        raise ValueError(f"circular dependency detected: {' -> '.join(cycle)}")

    return True

def find_cycle(services):
    visited = {}
    stack = []

    def dfs(node):
        visited[node] = 1
        stack.append(node)
        for dep in services[node].get('depends_on', []):
            if dep not in services:
                continue
            if visited.get(dep) == 1:
                idx = stack.index(dep)
                return stack[idx:] + [dep]
            if visited.get(dep) is None:
                res = dfs(dep)
                if res:
                    return res
        stack.pop()
        visited[node] = 2
        return None

    for n in sorted(services):
        if visited.get(n) is None:
            res = dfs(n)
            if res:
                return res
    return None

def get_services(data):
    try:
        validate_manifest(data)
    except ValueError as e:
        fail(str(e))
    return data['services'], data['environments']

def topo_order(services, subset=None):
    if subset is None:
        subset = set(services.keys())
    subset = set(subset)

    in_degree = {s: 0 for s in subset}
    adj = {s: [] for s in subset}

    for s in subset:
        for dep in services[s].get('depends_on', []):
            if dep in subset:
                adj[dep].append(s)
                in_degree[s] += 1

    order = []
    available = sorted([s for s in subset if in_degree[s] == 0])
    while available:
        next_available = []
        for s in available:
            order.append(s)
            for dependent in sorted(adj[s]):
                in_degree[dependent] -= 1
                if in_degree[dependent] == 0:
                    next_available.append(dependent)
        available = sorted(next_available)

    if len(order) != len(subset):
        fail("circular dependency detected")
    return order

def build_waves(services, subset):
    subset = set(subset)

    in_degree = {s: 0 for s in subset}
    adj = {s: [] for s in subset}

    for s in subset:
        for dep in services[s].get('depends_on', []):
            if dep in subset:
                adj[dep].append(s)
                in_degree[s] += 1

    waves = []
    available = sorted([s for s in subset if in_degree[s] == 0])
    while available:
        waves.append(available)
        next_available = []
        for s in available:
            for dependent in sorted(adj[s]):
                in_degree[dependent] -= 1
                if in_degree[dependent] == 0:
                    next_available.append(dependent)
        available = sorted(next_available)

    if sum(len(w) for w in waves) != len(subset):
        fail("circular dependency detected")
    return waves

def transitive_deps(services, name):
    if name not in services:
        fail(f"service not found: {name}")
    result = set()
    stack = [name]
    while stack:
        s = stack.pop()
        if s not in result:
            result.add(s)
            for dep in services[s].get('depends_on', []):
                if dep not in services:
                    fail(f"service {s} depends on undefined service: {dep}")
                stack.append(dep)
    return result

def service_path(svc):
    p = svc.get('path', '')
    if os.path.isabs(p):
        return p
    return os.path.join(APP_DIR, p)

def artifact_path(svc):
    return os.path.join(service_path(svc), 'build', 'artifact.txt')

def read_artifact(svc):
    try:
        with open(artifact_path(svc)) as f:
            return f.read().strip()
    except FileNotFoundError:
        return None

def deployment_file(env):
    return os.path.join(DEPLOYMENTS_DIR, f"{env}.json")

def load_deployment_state(env):
    return load_json(deployment_file(env), {})

def save_deployment_state(env, state):
    save_json(deployment_file(env), state)

def parse_opts(args, value_opts, flag_opts):
    values = {}
    flags = set()
    positionals = []
    i = 0
    while i < len(args):
        a = args[i]
        if a in value_opts:
            i += 1
            if i >= len(args):
                fail(f"{a} requires a value")
            values[a] = args[i]
        elif a in flag_opts:
            flags.add(a)
        elif a.startswith('--'):
            fail(f"unknown option: {a}")
        else:
            positionals.append(a)
        i += 1
    return values, flags, positionals

def cmd_validate(args):
    if args:
        fail("validate takes no arguments")
    data = load_manifest()
    try:
        validate_manifest(data)
    except ValueError as e:
        print(f"ERROR: {e}")
        sys.exit(1)
    print("VALID")

def cmd_order(args):
    if args:
        fail("order takes no arguments")
    data = load_manifest()
    services, _ = get_services(data)
    for s in topo_order(services):
        print(s)

def cmd_build(args):
    values, flags, positionals = parse_opts(args, {'--service'}, {'--parallel'})
    if positionals:
        fail("build does not accept positional arguments")

    service = values.get('--service')
    parallel = '--parallel' in flags

    data = load_manifest()
    services, _ = get_services(data)

    if service:
        subset = transitive_deps(services, service)
    else:
        subset = set(services.keys())

    if parallel:
        for wave in build_waves(services, subset):
            print(",".join(wave))
        return

    order = topo_order(services, subset)
    any_fail = False
    for s in order:
        svc = services[s]
        path = service_path(svc)
        if not os.path.isdir(path):
            print(f"BUILD {s} FAIL: service path does not exist")
            any_fail = True
            continue
        try:
            os.makedirs(os.path.join(path, 'build'), exist_ok=True)
            with open(os.path.join(path, 'build', 'artifact.txt'), 'w') as f:
                f.write(f"{s}:{int(time.time())}:built")
            print(f"BUILD {s} OK")
        except Exception as e:
            print(f"BUILD {s} FAIL: {e}")
            any_fail = True

    if any_fail:
        sys.exit(1)

def cmd_test(args):
    values, flags, positionals = parse_opts(args, {'--service'}, {'--fail-fast'})
    if positionals:
        fail("test does not accept positional arguments")

    service = values.get('--service')
    fail_fast = '--fail-fast' in flags

    data = load_manifest()
    services, _ = get_services(data)

    if service:
        if service not in services:
            fail(f"service not found: {service}")
        order = [service]
    else:
        order = topo_order(services)

    ensure_state()
    results = load_json(TEST_RESULTS_PATH, {})
    any_fail = False

    for s in order:
        if os.path.exists(artifact_path(services[s])):
            results[s] = {"pass": True, "timestamp": now_iso()}
            print(f"TEST {s} PASS")
        else:
            results[s] = {"pass": False, "timestamp": now_iso()}
            print(f"TEST {s} FAIL: not built")
            any_fail = True
            if fail_fast:
                break

    save_json(TEST_RESULTS_PATH, results)
    if any_fail:
        sys.exit(1)

def cmd_deploy(args):
    values, flags, positionals = parse_opts(args, {'--service'}, {'--dry-run'})
    if len(positionals) != 1:
        fail("deploy requires an environment")

    env = positionals[0]
    service = values.get('--service')
    dry_run = '--dry-run' in flags

    data = load_manifest()
    services, envs = get_services(data)

    if env not in envs:
        fail(f"environment not found: {env}")

    if service:
        subset = transitive_deps(services, service)
    else:
        subset = set(services.keys())

    order = topo_order(services, subset)
    ensure_state()

    if dry_run:
        print(f"DRY-RUN deploy to {env}:")
        for s in order:
            print(f"  Would deploy {s}")
        return

    test_results = load_json(TEST_RESULTS_PATH, {})
    state = load_deployment_state(env)
    any_fail = False

    for s in order:
        rec = test_results.get(s)
        if not rec or not rec.get("pass"):
            print(f"DEPLOY {s} -> {env} FAIL: tests not passing")
            any_fail = True
            break

        version = read_artifact(services[s])
        if version is None:
            print(f"DEPLOY {s} -> {env} FAIL: tests not passing")
            any_fail = True
            break

        state[s] = {"version": version, "deployed_at": now_iso()}
        print(f"DEPLOY {s} -> {env} OK")

    save_deployment_state(env, state)
    if any_fail:
        sys.exit(1)

def cmd_status(args):
    if len(args) > 1:
        fail("status takes at most one environment argument")

    data = load_manifest()
    _, envs = get_services(data)

    if args:
        env = args[0]
        if env not in envs:
            fail(f"environment not found: {env}")
        state = load_deployment_state(env)
        for s in sorted(state):
            rec = state[s]
            print(f"{s}: {rec.get('version', '')} (deployed at {rec.get('deployed_at', '')})")
    else:
        for env in sorted(envs):
            state = load_deployment_state(env)
            print(f"{env}: {len(state)} services deployed")

def cmd_rollback(args):
    if len(args) != 2:
        fail("rollback requires <environment> <service_name>")

    env, service = args
    ensure_state()
    state = load_deployment_state(env)

    if service not in state:
        print(f"ROLLBACK {service} from {env} FAIL: not deployed")
        sys.exit(1)

    del state[service]
    save_deployment_state(env, state)
    print(f"ROLLBACK {service} from {env} OK")

def print_tree(node, services, path, depth):
    print("  " * depth + node)
    if node in path:
        return
    path = path | {node}
    children = sorted([s for s in services if node in services[s].get('depends_on', [])])
    for child in children:
        print_tree(child, services, path, depth + 1)

def cmd_graph(args):
    values, flags, positionals = parse_opts(args, {'--format'}, set())
    if positionals:
        fail("graph does not accept positional arguments")

    fmt = values.get('--format', 'text')
    if fmt not in ('dot', 'text'):
        fail("graph format must be dot or text")

    data = load_manifest()
    services, _ = get_services(data)

    if fmt == 'dot':
        print("digraph pipeline {")
        for dep in sorted(services):
            dependents = sorted([s for s in services if dep in services[s].get('depends_on', [])])
            for dependent in dependents:
                print(f'  "{dep}" -> "{dependent}";')
        print("}")
    else:
        roots = sorted([s for s in services if not services[s].get('depends_on')])
        for root in roots:
            print_tree(root, services, set(), 0)

def main():
    if len(sys.argv) < 2:
        fail("no command given")

    cmd = sys.argv[1]
    args = sys.argv[2:]

    if cmd == 'validate':
        cmd_validate(args)
    elif cmd == 'order':
        cmd_order(args)
    elif cmd == 'build':
        cmd_build(args)
    elif cmd == 'test':
        cmd_test(args)
    elif cmd == 'deploy':
        cmd_deploy(args)
    elif cmd == 'status':
        cmd_status(args)
    elif cmd == 'rollback':
        cmd_rollback(args)
    elif cmd == 'graph':
        cmd_graph(args)
    else:
        fail(f"unknown command: {cmd}")

if __name__ == '__main__':
    main()
